contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient == address(this));

        uint beforeBalance = address(c).balance;

        bool reverted;
        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;

        assert(!reverted && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

